def average_word_length(s):
    words = s.split()
    if not words:
        return 0.0
    return sum(len(w) for w in words) / len(words)

def count_max_nesting_depth(s):
    depth = 0
    max_depth = 0
    for ch in s:
        if ch in '([{':
            depth += 1
            max_depth = max(max_depth, depth)
        elif ch in ')]}':
            depth = max(0, depth - 1)
    return max_depth

def find_repeated_words(s):
    words = [w.lower() for w in s.split()]
    counts = {}
    order = []
    for w in words:
        if w not in counts:
            counts[w] = 0
            order.append(w)
        counts[w] += 1
    return [w for w in order if counts[w] > 1]

def char_difference_count(s1, s2):
    if len(s1) != len(s2):
        return -1
    return sum(1 for a, b in zip(s1, s2) if a != b)

def convert_spaces_to_underscores(s):
    import re
    return re.sub(r'\s+', '_', s.strip())

def count_common_prefix_length(a, b):
    n = min(len(a), len(b))
    i = 0
    while i < n and a[i] == b[i]:
        i += 1
    return i

def count_lines(s):
    if not s:
        return 0
    return s.count('\n') + 1
